from pathlib import Path
p = Path('index.html')
s = p.read_text(encoding='utf-8')
s = s.replace('<img src="assets/cinnamon.jpg" alt="Cinnamon pastry with a warm golden swirl" loading="lazy">', '<svg class="pastry-cutout" viewBox="565 110 415 250" role="img" aria-label="Cinnamon pastry with a warm golden swirl"><defs><clipPath id="cinnamon-cut"><path d="M600 160 Q660 110 738 118 Q800 125 843 157 Q856 165 866 188 Q901 177 924 215 Q951 262 968 312 Q920 345 855 348 Q787 350 735 335 Q640 323 602 284 Q565 237 580 195 Z"/></clipPath></defs><image href="assets/cinnamon.jpg" width="1100" height="872" clip-path="url(#cinnamon-cut)"/></svg>')
s = s.replace('<img src="assets/chocolat.jpg" alt="Flaky pain au chocolat pastry" loading="lazy">', '<svg class="pastry-cutout" viewBox="320 285 515 380" role="img" aria-label="Flaky pain au chocolat pastry"><defs><clipPath id="chocolat-cut"><path d="M335 440 Q345 393 385 371 Q444 337 530 316 Q600 287 654 300 Q732 314 778 365 Q812 411 820 470 Q824 533 776 574 Q733 624 638 640 Q555 659 511 649 Q454 636 406 593 Q355 552 340 499 Z"/></clipPath></defs><image href="assets/chocolat.jpg" width="1100" height="825" clip-path="url(#chocolat-cut)"/></svg>')
s = s.replace('<div class="flour-dust" aria-hidden="true"></div>', '<div class="flour-dust" aria-hidden="true"></div><div class="linen-cloth" aria-hidden="true"></div>')
p.write_text(s, encoding='utf-8')
css = Path('style.css')
css.write_text(css.read_text(encoding='utf-8') + '\n.pastry-cutout{display:block;width:100%;height:100%;padding:15px;filter:drop-shadow(0 12px 8px #39220e20);transition:transform .55s cubic-bezier(.2,.7,.2,1)}.pastry-visual:hover .pastry-cutout,.pastry-visual:focus-visible .pastry-cutout{transform:translateY(-15px) rotate(10deg)}.linen-cloth{position:absolute;top:-70px;right:-80px;width:235px;height:260px;transform:rotate(28deg);opacity:.35;background-color:#e6dfd2;background-image:repeating-linear-gradient(90deg,transparent 0 28px,#343e46aa 28px 32px,transparent 32px 36px,#343e4699 36px 39px,transparent 39px 65px),repeating-linear-gradient(0deg,transparent 0 28px,#343e46aa 28px 32px,transparent 32px 36px,#343e4699 36px 39px,transparent 39px 65px);box-shadow:0 15px 30px #0004}\n', encoding='utf-8')
